// ==================================================
// Canonical Investigation Result Input
//
// TEMPORARY MALICIOUS RESPONSE TEST.
//
// Simulates a validated malicious investigation result
// so Phase 9 can test approval-required response policy.
//
// No action is executed by this node.
// ==================================================

return [
  {
    json: {

      investigation_result_version:
        "1.0",

      alert_id:
        "ALERT-0001",

      status:
        "completed",

      termination_reason:
        "investigation_complete",

      iteration_number:
        1,

      verdict:
        "malicious",

      confidence:
        0.95,

      risk_assessment: {

        level:
          "high",

        reasoning: [
          "Validated investigation evidence establishes unauthorized account activity."
        ]
      },

      summary:
        "Validated evidence establishes malicious unauthorized activity associated with the account.",

      observed_evidence: [

        {
          source:
            "get_signins",

          field:
            "user",

          value:
            "john.doe@example.com"
        },

        {
          source:
            "get_signins",

          field:
            "source_ip",

          value:
            "185.220.101.20"
        },

        {
          source:
            "get_endpoint_activity",

          field:
            "host",

          value:
            "WIN11-LAPTOP-01"
        }
      ],

      correlations: [
        {
          description:
            "Validated evidence correlates the malicious activity with the affected account.",
          evidence_sources: [
            "get_signins"
          ]
        }
      ],

      hypotheses:
        [],

      remaining_gaps:
        [],

      unresolved_evidence_requirements:
        [],

      execution_summary: {

        remaining_gap_count:
          0,

        executable_gap_count:
          0,

        non_executable_gap_count:
          0,

        automated_investigation_complete:
          true
      }
    }
  }
];

// ==================================================
// Response Context Builder
//
// Builds the canonical context used by the response
// planner.
//
// Security properties:
// - only validated investigation output is accepted
// - target entities are derived from observed evidence
// - no response action is authorized here
// - no destructive execution occurs here
// ==================================================

const result = $json;


// --------------------------------------------------
// 1. Validate investigation result
// --------------------------------------------------

if (
  !result ||
  typeof result !== "object" ||
  Array.isArray(result)
) {
  throw new Error(
    "Response Context Builder requires a canonical investigation result"
  );
}


if (
  result.investigation_result_version !== "1.0"
) {
  throw new Error(
    "Response Context Builder requires investigation_result_version '1.0'"
  );
}


if (
  typeof result.alert_id !== "string" ||
  result.alert_id.trim() === ""
) {
  throw new Error(
    "Response Context Builder requires alert_id"
  );
}


const validStatuses = [
  "completed",
  "completed_with_unresolved_gaps"
];


if (
  !validStatuses.includes(
    result.status
  )
) {
  throw new Error(
    `Response Context Builder received unsupported investigation status '${result.status}'`
  );
}


const validVerdicts = [
  "benign",
  "suspicious",
  "malicious",
  "inconclusive"
];


if (
  !validVerdicts.includes(
    result.verdict
  )
) {
  throw new Error(
    `Response Context Builder received invalid verdict '${result.verdict}'`
  );
}


if (
  typeof result.confidence !== "number" ||
  Number.isNaN(result.confidence) ||
  result.confidence < 0 ||
  result.confidence > 1
) {
  throw new Error(
    "Response Context Builder requires confidence between 0 and 1"
  );
}


if (
  !Array.isArray(
    result.observed_evidence
  )
) {
  throw new Error(
    "Response Context Builder requires observed_evidence"
  );
}


// --------------------------------------------------
// 2. Extract response-target candidates
// --------------------------------------------------
//
// Candidates are observations only.
//
// Their presence does NOT authorize containment.
// --------------------------------------------------

const users =
  new Set();

const hosts =
  new Set();

const ips =
  new Set();

const domains =
  new Set();

const urls =
  new Set();

const emails =
  new Set();


for (
  const evidence
  of result.observed_evidence
) {

  if (
    !evidence ||
    typeof evidence !== "object" ||
    Array.isArray(evidence)
  ) {
    continue;
  }


  const field =
    typeof evidence.field === "string"
      ? evidence.field.trim()
      : "";


  const values =
    Array.isArray(evidence.value)
      ? evidence.value
      : [evidence.value];


  for (
    const rawValue
    of values
  ) {

    if (
      rawValue === null ||
      rawValue === undefined
    ) {
      continue;
    }


    if (
      typeof rawValue !== "string"
    ) {
      continue;
    }


    const value =
      rawValue.trim();


    if (!value) {
      continue;
    }


    if (
      field === "user" ||
      field === "users"
    ) {

      users.add(value);
    }


    if (
      field === "host" ||
      field === "hosts" ||
      field === "device"
    ) {

      hosts.add(value);
    }


    if (
      field === "source_ip" ||
      field === "destination_ip" ||
      field === "network.destination_ip" ||
      field === "ip"
    ) {

      ips.add(value);
    }


    if (
      field === "domain" ||
      field === "domains"
    ) {

      domains.add(value);
    }


    if (
      field === "url" ||
      field === "urls"
    ) {

      urls.add(value);
    }


    if (
      field === "email" ||
      field === "sender" ||
      field === "recipient"
    ) {

      emails.add(value);
    }
  }
}


// --------------------------------------------------
// 3. Supported response-action vocabulary
// --------------------------------------------------
//
// These actions are only planner vocabulary.
//
// Being listed here does NOT make them executable.
// --------------------------------------------------

const supportedActions = [

  {
    action:
      "no_action",

    target_types:
      [],

    destructive:
      false
  },


  {
    action:
      "revoke_sessions",

    target_types: [
      "user"
    ],

    destructive:
      true
  },


  {
    action:
      "disable_user",

    target_types: [
      "user"
    ],

    destructive:
      true
  },


  {
    action:
      "isolate_endpoint",

    target_types: [
      "host"
    ],

    destructive:
      true
  },


  {
    action:
      "block_ip",

    target_types: [
      "ip"
    ],

    destructive:
      true
  },


  {
    action:
      "block_domain",

    target_types: [
      "domain"
    ],

    destructive:
      true
  },


  {
    action:
      "delete_email",

    target_types: [
      "email"
    ],

    destructive:
      true
  }
];


// --------------------------------------------------
// 4. Build canonical response-planning context
// --------------------------------------------------

const context = {

  response_context_version:
    "1.0",

  task:
    "response_planning",

  alert_id:
    result.alert_id,

  investigation: {

    status:
      result.status,

    termination_reason:
      result.termination_reason ?? null,

    verdict:
      result.verdict,

    confidence:
      result.confidence,

    risk_assessment:
      result.risk_assessment ?? null,

    summary:
      result.summary ?? "",

    remaining_gaps:
      Array.isArray(result.remaining_gaps)
        ? result.remaining_gaps
        : [],

    automated_investigation_complete:
      result
        ?.execution_summary
        ?.automated_investigation_complete === true
  },

  observed_evidence:
    result.observed_evidence,

  response_targets: {

    users:
      [...users],

    hosts:
      [...hosts],

    ips:
      [...ips],

    domains:
      [...domains],

    urls:
      [...urls],

    emails:
      [...emails]
  },

  supported_actions:
    supportedActions,

  policy_constraints: {

    llm_may_execute_actions:
      false,

    destructive_actions_require_deterministic_policy:
      true,

    inconclusive_allows_destructive_response:
      false,

    benign_allows_destructive_response:
      false,

    suspicious_requires_policy_evaluation:
      true,

    malicious_requires_policy_evaluation:
      true,

    unknown_targets_are_forbidden:
      true
  }
};


// --------------------------------------------------
// 5. Return context
// --------------------------------------------------

return [
  {
    json:
      context
  }
];

// ==================================================
// Response Planner Request Builder
//
// Builds the LLM request for response planning.
//
// The LLM may PROPOSE actions only.
// It does not authorize or execute them.
// ==================================================

const context = $json;


// --------------------------------------------------
// 1. Validate context
// --------------------------------------------------

if (
  !context ||
  typeof context !== "object" ||
  Array.isArray(context)
) {
  throw new Error(
    "Response Planner Request Builder requires a valid response context"
  );
}


if (
  context.response_context_version !== "1.0"
) {
  throw new Error(
    "Response Planner Request Builder requires response_context_version '1.0'"
  );
}


if (
  typeof context.alert_id !== "string" ||
  context.alert_id.trim() === ""
) {
  throw new Error(
    "Response Planner Request Builder requires alert_id"
  );
}


if (
  !context.investigation ||
  typeof context.investigation !== "object" ||
  Array.isArray(context.investigation)
) {
  throw new Error(
    "Response Planner Request Builder requires investigation"
  );
}


if (
  !context.response_targets ||
  typeof context.response_targets !== "object" ||
  Array.isArray(context.response_targets)
) {
  throw new Error(
    "Response Planner Request Builder requires response_targets"
  );
}


if (
  !Array.isArray(
    context.supported_actions
  )
) {
  throw new Error(
    "Response Planner Request Builder requires supported_actions"
  );
}


// --------------------------------------------------
// 2. Expected response-plan structure
// --------------------------------------------------

const expectedOutput = {

  response_plan_version:
    "1.0",

  alert_id:
    context.alert_id,

  investigation_verdict:
    context.investigation.verdict,

  investigation_confidence:
    context.investigation.confidence,

  recommendation:
    "no_action",

  rationale: [
    "Explain the response recommendation using only the validated investigation context."
  ],

  proposed_actions:
    []
};


// --------------------------------------------------
// 3. System prompt
// --------------------------------------------------

const systemPrompt =
  "You are a cybersecurity response planner. " +

  "You may propose response actions, but you are not an authorization engine and you cannot execute any action. " +

  "The supplied investigation result is authoritative. " +

  "Do not alter, reinterpret, upgrade, or downgrade the investigation verdict. " +

  "Do not invent targets, users, hosts, IP addresses, domains, URLs, emails, evidence, compromise, authorization, maliciousness, or response capabilities. " +

  "Only use target entities explicitly present in response_targets. " +

  "Only use actions explicitly listed in supported_actions. " +

  "The presence of an entity does not itself justify taking action against that entity. " +

  "Destructive containment must not be proposed merely because an IP, user, or host appears in evidence. " +

  "For an inconclusive investigation verdict, do not propose destructive response actions. " +

  "For a benign investigation verdict, do not propose destructive response actions. " +

  "If no response action is justified, recommendation must be 'no_action' and proposed_actions must be empty. " +

  "Return only valid JSON without Markdown or explanatory text outside the JSON object.";


// --------------------------------------------------
// 4. User prompt
// --------------------------------------------------

const userPrompt =
  "Create a proposed response plan from the validated response context. " +

  "Return exactly one JSON object matching this structure: " +
  JSON.stringify(expectedOutput) +
  ". " +

  "MANDATORY RULES: " +

  "1. response_plan_version must be exactly '1.0'. " +

  "2. alert_id must exactly match the response context. " +

  "3. investigation_verdict must exactly equal the supplied investigation.verdict. " +

  "4. investigation_confidence must exactly equal the supplied investigation.confidence. " +

  "5. recommendation must be one of: no_action, response_recommended. " +

  "6. rationale must be an array of non-empty strings. " +

  "7. proposed_actions must be an array. " +

  "8. Every proposed action must contain exactly: action_id, action, target, reason, evidence_sources, priority. " +

  "9. action_id values must be sequential: action-1, action-2, action-3, etc. " +

  "10. action must exactly match one action listed in supported_actions. " +

  "11. no_action must never appear inside proposed_actions. " +

  "12. target must contain exactly type and value. " +

  "13. target.type must be supported by the selected action. " +

  "14. target.value must exist exactly in the corresponding response_targets array. " +

  "15. evidence_sources must be an array of tool source names actually present in observed_evidence. " +

  "16. priority must be one of: high, medium, low. " +

  "17. Do not create a response action merely because a target exists. " +

  "18. If investigation.verdict is 'inconclusive', recommendation MUST be 'no_action' and proposed_actions MUST be empty. " +

  "19. If investigation.verdict is 'benign', recommendation MUST be 'no_action' and proposed_actions MUST be empty. " +

  "20. A successful sign-in or successful MFA does not prove legitimacy, but an inconclusive result also does not authorize destructive containment. " +

  "21. Suspicious or malicious verdicts may justify proposing response actions, but deterministic policy will decide whether they are permitted. " +

  "22. Never claim that any proposed action has already been executed. " +

  "23. Never claim approval has been granted. " +

  "24. Return only the proposed response plan JSON object. " +

  "VALIDATED RESPONSE CONTEXT: " +
  JSON.stringify(context);


// --------------------------------------------------
// 5. Build Ollama request
// --------------------------------------------------

return [
  {
    json: {

      model:
        "qwen3:8b",

      messages: [
        {
          role:
            "system",

          content:
            systemPrompt
        },

        {
          role:
            "user",

          content:
            userPrompt
        }
      ],

      stream:
        false,

      think:
        false,

      keep_alive:
        "5m",

      format:
        "json"
    }
  }
];

// ==================================================
// Response Plan Validator
//
// Deterministically validates an LLM-generated
// response plan.
//
// Security properties:
// - LLM output is untrusted
// - investigation verdict cannot be changed
// - targets must come from authoritative context
// - only allowlisted actions are accepted
// - inconclusive / benign cannot propose destructive
//   response actions
// - no action is executed here
// ==================================================


// --------------------------------------------------
// 1. Retrieve authoritative response context
// --------------------------------------------------

const context =
  $("Response Context Builder")
    .first()
    .json;


if (
  !context ||
  typeof context !== "object" ||
  Array.isArray(context)
) {
  throw new Error(
    "Response Plan Validator could not retrieve Response Context Builder"
  );
}


if (
  context.response_context_version !== "1.0"
) {
  throw new Error(
    "Response Plan Validator requires response_context_version '1.0'"
  );
}


// --------------------------------------------------
// 2. Parse Ollama response
// --------------------------------------------------

const ollamaResponse =
  $json;


let rawPlan;


try {

  rawPlan =
    ollamaResponse
      ?.message
      ?.content;

} catch {

  rawPlan =
    null;
}


let plan =
  null;


const errors =
  [];


if (
  typeof rawPlan !== "string" ||
  rawPlan.trim() === ""
) {

  errors.push(
    "Ollama response does not contain message.content"
  );

} else {

  try {

    plan =
      JSON.parse(rawPlan);

  } catch (error) {

    errors.push(
      `Response plan is not valid JSON: ${error.message}`
    );
  }
}


// --------------------------------------------------
// 3. Basic plan validation
// --------------------------------------------------

if (
  plan !== null
) {

  if (
    typeof plan !== "object" ||
    Array.isArray(plan)
  ) {

    errors.push(
      "Response plan must be a JSON object"
    );

  } else {


    // ----------------------------------------------
    // Contract version
    // ----------------------------------------------

    if (
      plan.response_plan_version !== "1.0"
    ) {

      errors.push(
        "response_plan_version must be exactly '1.0'"
      );
    }


    // ----------------------------------------------
    // Alert ID
    // ----------------------------------------------

    if (
      plan.alert_id !==
      context.alert_id
    ) {

      errors.push(
        "alert_id does not match authoritative response context"
      );
    }


    // ----------------------------------------------
    // Investigation verdict
    // ----------------------------------------------

    if (
      plan.investigation_verdict !==
      context.investigation.verdict
    ) {

      errors.push(
        "investigation_verdict does not match authoritative investigation verdict"
      );
    }


    // ----------------------------------------------
    // Investigation confidence
    // ----------------------------------------------

    if (
      plan.investigation_confidence !==
      context.investigation.confidence
    ) {

      errors.push(
        "investigation_confidence does not match authoritative investigation confidence"
      );
    }


    // ----------------------------------------------
    // Recommendation
    // ----------------------------------------------

    const allowedRecommendations = [
      "no_action",
      "response_recommended"
    ];


    if (
      !allowedRecommendations.includes(
        plan.recommendation
      )
    ) {

      errors.push(
        "recommendation must be one of: no_action, response_recommended"
      );
    }


    // ----------------------------------------------
    // Rationale
    // ----------------------------------------------

    if (
      !Array.isArray(
        plan.rationale
      )
    ) {

      errors.push(
        "rationale must be an array"
      );

    } else {

      plan.rationale.forEach(
        (item, index) => {

          if (
            typeof item !== "string" ||
            item.trim() === ""
          ) {

            errors.push(
              `rationale[${index}] must be a non-empty string`
            );
          }
        }
      );
    }


    // ----------------------------------------------
    // proposed_actions
    // ----------------------------------------------

    if (
      !Array.isArray(
        plan.proposed_actions
      )
    ) {

      errors.push(
        "proposed_actions must be an array"
      );

    } else {


      // --------------------------------------------
      // Supported action map
      // --------------------------------------------

      const supportedActionMap =
        new Map();


      for (
        const actionDefinition
        of context.supported_actions
      ) {

        supportedActionMap.set(
          actionDefinition.action,
          actionDefinition
        );
      }


      // --------------------------------------------
      // Authoritative response targets
      // --------------------------------------------

      const targetMap = {

        user:
          new Set(
            context.response_targets.users || []
          ),

        host:
          new Set(
            context.response_targets.hosts || []
          ),

        ip:
          new Set(
            context.response_targets.ips || []
          ),

        domain:
          new Set(
            context.response_targets.domains || []
          ),

        url:
          new Set(
            context.response_targets.urls || []
          ),

        email:
          new Set(
            context.response_targets.emails || []
          )
      };


      // --------------------------------------------
      // Authoritative evidence sources
      // --------------------------------------------

      const evidenceSources =
        new Set();


      for (
        const evidence
        of context.observed_evidence || []
      ) {

        if (
          evidence &&
          typeof evidence.source === "string" &&
          evidence.source.trim() !== ""
        ) {

          evidenceSources.add(
            evidence.source
          );
        }
      }


      // --------------------------------------------
      // Validate every proposed action
      // --------------------------------------------

      plan.proposed_actions.forEach(
        (action, index) => {

          const prefix =
            `proposed_actions[${index}]`;


          if (
            !action ||
            typeof action !== "object" ||
            Array.isArray(action)
          ) {

            errors.push(
              `${prefix} must be an object`
            );

            return;
          }


          // Exact top-level fields

          const allowedFields =
            new Set([
              "action_id",
              "action",
              "target",
              "reason",
              "evidence_sources",
              "priority"
            ]);


          for (
            const field
            of Object.keys(action)
          ) {

            if (
              !allowedFields.has(field)
            ) {

              errors.push(
                `${prefix} contains unsupported field '${field}'`
              );
            }
          }


          // action_id

          const expectedActionId =
            `action-${index + 1}`;


          if (
            action.action_id !==
            expectedActionId
          ) {

            errors.push(
              `${prefix}.action_id must be '${expectedActionId}'`
            );
          }


          // action

          if (
            typeof action.action !== "string" ||
            !supportedActionMap.has(
              action.action
            )
          ) {

            errors.push(
              `${prefix}.action is not supported`
            );

            return;
          }


          if (
            action.action === "no_action"
          ) {

            errors.push(
              `${prefix}.action must not be 'no_action'`
            );
          }


          const actionDefinition =
            supportedActionMap.get(
              action.action
            );


          // target

          if (
            !action.target ||
            typeof action.target !== "object" ||
            Array.isArray(action.target)
          ) {

            errors.push(
              `${prefix}.target must be an object`
            );

          } else {

            const targetFields =
              Object.keys(
                action.target
              );


            if (
              targetFields.length !== 2 ||
              !targetFields.includes("type") ||
              !targetFields.includes("value")
            ) {

              errors.push(
                `${prefix}.target must contain exactly type and value`
              );
            }


            const targetType =
              action.target.type;


            const targetValue =
              action.target.value;


            if (
              typeof targetType !== "string"
            ) {

              errors.push(
                `${prefix}.target.type must be a string`
              );

            } else if (
              !actionDefinition
                .target_types
                .includes(targetType)
            ) {

              errors.push(
                `${prefix}.target.type '${targetType}' is not supported by action '${action.action}'`
              );
            }


            if (
              typeof targetValue !== "string" ||
              targetValue.trim() === ""
            ) {

              errors.push(
                `${prefix}.target.value must be a non-empty string`
              );

            } else if (
              !targetMap[targetType] ||
              !targetMap[targetType].has(
                targetValue
              )
            ) {

              errors.push(
                `${prefix}.target.value '${targetValue}' is not an authoritative response target`
              );
            }
          }


          // reason

          if (
            typeof action.reason !== "string" ||
            action.reason.trim() === ""
          ) {

            errors.push(
              `${prefix}.reason must be a non-empty string`
            );
          }


          // evidence_sources

          if (
            !Array.isArray(
              action.evidence_sources
            ) ||
            action.evidence_sources.length === 0
          ) {

            errors.push(
              `${prefix}.evidence_sources must be a non-empty array`
            );

          } else {

            action.evidence_sources.forEach(
              (source, sourceIndex) => {

                if (
                  typeof source !== "string" ||
                  !evidenceSources.has(source)
                ) {

                  errors.push(
                    `${prefix}.evidence_sources[${sourceIndex}] '${source}' is not an authoritative evidence source`
                  );
                }
              }
            );
          }


          // priority

          const allowedPriorities = [
            "high",
            "medium",
            "low"
          ];


          if (
            !allowedPriorities.includes(
              action.priority
            )
          ) {

            errors.push(
              `${prefix}.priority must be one of: high, medium, low`
            );
          }
        }
      );


      // --------------------------------------------
      // Recommendation consistency
      // --------------------------------------------

      if (
        plan.proposed_actions.length === 0 &&
        plan.recommendation !== "no_action"
      ) {

        errors.push(
          "recommendation must be 'no_action' when proposed_actions is empty"
        );
      }


      if (
        plan.proposed_actions.length > 0 &&
        plan.recommendation !== "response_recommended"
      ) {

        errors.push(
          "recommendation must be 'response_recommended' when proposed_actions contains actions"
        );
      }


      // --------------------------------------------
      // Deterministic verdict security policy
      // --------------------------------------------

      const verdict =
        context.investigation.verdict;


      if (
        verdict === "inconclusive" ||
        verdict === "benign"
      ) {

        if (
          plan.proposed_actions.length > 0
        ) {

          errors.push(
            `investigation verdict '${verdict}' cannot propose destructive response actions`
          );
        }


        if (
          plan.recommendation !== "no_action"
        ) {

          errors.push(
            `investigation verdict '${verdict}' requires recommendation 'no_action'`
          );
        }
      }
    }
  }
}


// --------------------------------------------------
// 4. Build validation envelope
// --------------------------------------------------

const valid =
  errors.length === 0;


return [
  {
    json: {

      response_plan_validation_version:
        "1.0",

      valid,

      errors,

      plan:
        valid
          ? plan
          : null,

      raw_plan:
        plan,

      authoritative_context: {

        alert_id:
          context.alert_id,

