      json: {

        response_policy_evaluation_version:
          "1.0",

        alert_id:
          context.alert_id,

        decision:
          "reject",

        reason:
          "invalid_response_plan",

        investigation_verdict:
          context.investigation.verdict,

        investigation_confidence:
          context.investigation.confidence,

        action_decisions:
          [],

        validation_errors:
          Array.isArray(validation.errors)
            ? validation.errors
            : [],

        execution_allowed:
          false,

        human_approval_required:
          false
      }
    }
  ];
}


// --------------------------------------------------
// 4. Validate canonical plan
// --------------------------------------------------

const plan =
  validation.plan;


if (
  !plan ||
  typeof plan !== "object" ||
  Array.isArray(plan)
) {
  throw new Error(
    "Response Policy Evaluator requires validation.plan when valid=true"
  );
}


if (
  plan.alert_id !== context.alert_id
) {
  throw new Error(
    "Response Policy Evaluator detected alert_id mismatch"
  );
}


if (
  plan.investigation_verdict !==
  context.investigation.verdict
) {
  throw new Error(
    "Response Policy Evaluator detected verdict mismatch"
  );
}


if (
  plan.investigation_confidence !==
  context.investigation.confidence
) {
  throw new Error(
    "Response Policy Evaluator detected confidence mismatch"
  );
}


if (
  !Array.isArray(plan.proposed_actions)
) {
  throw new Error(
    "Response Policy Evaluator requires proposed_actions"
  );
}


// --------------------------------------------------
// 5. Deterministic response policy
// --------------------------------------------------
//
// Phase 9 conservative policy:
//
// benign:
//   destructive actions forbidden
//
// inconclusive:
//   destructive actions forbidden
//
// suspicious:
//   destructive actions may only proceed to
//   human approval
//
// malicious:
//   destructive actions may only proceed to
//   human approval
//
// automatic execution is intentionally disabled
// during this phase.
// --------------------------------------------------

const policy = {

  policy_version:
    "1.0",

  automatic_execution_enabled:
    false,

  verdicts: {

    benign: {
      destructive_response:
        "forbidden"
    },

    inconclusive: {
      destructive_response:
        "forbidden"
    },

    suspicious: {
      destructive_response:
        "approval_required"
    },

    malicious: {
      destructive_response:
        "approval_required"
    }
  },

  actions: {

