// --------------------------------------------------
// 7. Evaluate proposed actions
// --------------------------------------------------

const verdict =
  context.investigation.verdict;


const verdictPolicy =
  policy.verdicts[verdict];


if (!verdictPolicy) {
  throw new Error(
    `No response policy exists for verdict '${verdict}'`
  );
}


const actionDecisions =
  [];


let hasRejectedActions =
  false;

let hasApprovalRequiredActions =
  false;

let hasAutomaticActions =
  false;


for (
  const action
  of plan.proposed_actions
) {

  const actionPolicy =
    policy.actions[action.action];


  if (!actionPolicy) {

    hasRejectedActions =
      true;


    actionDecisions.push({

      action_id:
        action.action_id,

      action:
        action.action,

      target:
        action.target,

      decision:
        "reject",

      reason:
        "action_not_defined_in_response_policy"
    });


    continue;
  }


  // ----------------------------------------------
  // Target-type policy validation
  // ----------------------------------------------

  if (
    action.target?.type !==
    actionPolicy.required_target_type
  ) {

    hasRejectedActions =
      true;


    actionDecisions.push({

      action_id:
        action.action_id,

      action:
        action.action,

      target:
        action.target,

      decision:
        "reject",

      reason:
        "target_type_not_allowed_by_policy"
    });


    continue;
  }


  // ----------------------------------------------
  // Verdict policy
  // ----------------------------------------------

  if (
    verdictPolicy.destructive_response ===
    "forbidden"
  ) {

    hasRejectedActions =
      true;


    actionDecisions.push({

      action_id:
        action.action_id,

      action:
        action.action,

      target:
        action.target,

      decision:
        "reject",

      reason:
        `destructive_response_forbidden_for_${verdict}_verdict`
    });


    continue;
  }


  // ----------------------------------------------
  // Human approval policy
  // ----------------------------------------------

  if (
    verdictPolicy.destructive_response ===
      "approval_required" ||
    actionPolicy.mode ===
      "approval_required"
  ) {

    hasApprovalRequiredActions =
      true;


    actionDecisions.push({

      action_id:
        action.action_id,

      action:
        action.action,

      target:
        action.target,

      priority:
        action.priority,

      reason:
        action.reason,

      evidence_sources:
        action.evidence_sources,

      decision:
        "approval_required",

      policy_reason:
        "destructive_response_requires_human_approval"
    });


    continue;
  }


  // ----------------------------------------------
  // Automatic execution
  //
  // Disabled in Phase 9.
  // ----------------------------------------------

  if (
    actionPolicy.mode === "automatic" &&
    policy.automatic_execution_enabled === true
  ) {

    hasAutomaticActions =
      true;


    actionDecisions.push({

      action_id:
        action.action_id,

      action:
        action.action,

      target:
        action.target,

      priority:
        action.priority,

      reason:
        action.reason,

      evidence_sources:
        action.evidence_sources,

      decision:
        "automatic_allowed",

      policy_reason:
        "automatic_execution_allowed_by_policy"
    });


    continue;
  }


  // ----------------------------------------------
  // Fail closed
  // ----------------------------------------------

  hasRejectedActions =
    true;


  actionDecisions.push({

    action_id:
      action.action_id,

    action:
      action.action,

    target:
      action.target,

    decision:
      "reject",

    reason:
      "no_authorizing_response_policy"
  });
}


// --------------------------------------------------
// 8. Determine global decision
// --------------------------------------------------

let decision;
let reason;


if (
  hasRejectedActions
) {

  decision =
    "reject";

  reason =
    "one_or_more_actions_rejected_by_policy";

} else if (
  hasApprovalRequiredActions
) {

  decision =
    "approval_required";

  reason =
    "human_approval_required";

} else if (
  hasAutomaticActions
) {

  decision =
    "automatic_allowed";

  reason =
    "automatic_execution_allowed_by_policy";

} else {

  decision =
    "no_action";

  reason =
    "no_executable_response_actions";
}


// --------------------------------------------------
// 9. Return policy evaluation
// --------------------------------------------------

return [
  {
    json: {

      response_policy_evaluation_version:
        "1.0",

      policy_version:
        policy.policy_version,

      alert_id:
        context.alert_id,

      decision,

      reason,

      investigation_verdict:
        context.investigation.verdict,

      investigation_confidence:
        context.investigation.confidence,

      action_decisions:
        actionDecisions,

      execution_allowed:
        decision === "automatic_allowed",

      human_approval_required:
        decision === "approval_required"
    }
  }
];

