) {

  if (
    approvedActionIds !== null &&
    approvedActionIds.length > 0
  ) {
    errors.push(
      "approved_action_ids must be empty when decision='reject'"
    );
  }
}


// --------------------------------------------------
// 7. Build canonical approved action set
// --------------------------------------------------

const valid =
  errors.length === 0;


let authorizedActions =
  [];


if (
  valid &&
  decisionInput.decision === "approve"
) {

  authorizedActions =
    request.actions.map(
      action => ({

        action_id:
          action.action_id,

        action:
          action.action,

        target:
          action.target,

        priority:
          action.priority,

        reason:
          action.reason,

        evidence_sources:
          action.evidence_sources,

        approval_request_id:
          request.approval_request_id,

        approved_by:
          decisionInput.approver.identifier,

        approved_at:
          decisionInput.decided_at
      })
    );
}


// --------------------------------------------------
// 8. Return validation envelope
// --------------------------------------------------

return [
  {
    json: {

      approval_validation_version:
        "1.0",

      valid,

      errors,

      approval_request_id:
        request.approval_request_id,

      alert_id:
        request.alert_id,

      decision:
        valid
          ? decisionInput.decision
          : null,

      approved:
        valid &&
        decisionInput.decision === "approve",

      rejected:
        valid &&
        decisionInput.decision === "reject",

      authorized_actions:
        authorizedActions,

      execution_allowed:
        valid &&
        decisionInput.decision === "approve" &&
        authorizedActions.length > 0,

      approver:
        valid
          ? decisionInput.approver
          : null
    }
  }
];

// ==================================================
// Authorized Response Actions
//
// Produces the canonical execution-ready authorization
// envelope.
//
// IMPORTANT:
// - This node still does NOT execute anything.
// - It represents the security boundary immediately
//   before a future Response Executor.
// ==================================================

const approval =
  $json;


// --------------------------------------------------
// 1. Validate approval envelope
// --------------------------------------------------

if (
  !approval ||
  typeof approval !== "object" ||
  Array.isArray(approval)
) {
  throw new Error(
    "Authorized Response Actions requires an approval validation envelope"
  );
}


if (
  approval.approval_validation_version !== "1.0"
) {
  throw new Error(
    "Authorized Response Actions requires approval_validation_version '1.0'"
  );
}


if (
  approval.valid !== true
) {
  throw new Error(
    "Authorized Response Actions requires valid=true"
  );
}


if (
  approval.approved !== true
) {
  throw new Error(
    "Authorized Response Actions requires approved=true"
  );
}


if (
  approval.execution_allowed !== true
) {
  throw new Error(
    "Authorized Response Actions requires execution_allowed=true"
  );
}


if (
  typeof approval.approval_request_id !== "string" ||
  approval.approval_request_id.trim() === ""
) {
  throw new Error(
    "Authorized Response Actions requires approval_request_id"
  );
}


if (
  typeof approval.alert_id !== "string" ||
  approval.alert_id.trim() === ""
) {
  throw new Error(
    "Authorized Response Actions requires alert_id"
  );
}


if (
  !Array.isArray(approval.authorized_actions) ||
  approval.authorized_actions.length === 0
) {
  throw new Error(
    "Authorized Response Actions requires at least one authorized action"
  );
}


// --------------------------------------------------
// 2. Validate authorized actions
// --------------------------------------------------

const supportedActions =
  new Set([
    "revoke_sessions",
    "disable_user",
    "isolate_endpoint",
    "block_ip",
    "block_domain",
    "delete_email"
  ]);


const canonicalActions =
  approval.authorized_actions.map(
    (action, index) => {

      if (
        !action ||
        typeof action !== "object" ||
        Array.isArray(action)
      ) {
        throw new Error(
          `authorized_actions[${index}] must be an object`
        );
      }


      if (
        typeof action.action_id !== "string" ||
        action.action_id.trim() === ""
      ) {
        throw new Error(
          `authorized_actions[${index}].action_id is required`
        );
      }


      if (
        typeof action.action !== "string" ||
        !supportedActions.has(action.action)
      ) {
        throw new Error(
          `authorized_actions[${index}].action is unsupported`
        );
      }


      if (
        !action.target ||
        typeof action.target !== "object" ||
        Array.isArray(action.target)
      ) {
        throw new Error(
          `authorized_actions[${index}].target is required`
        );
      }


      if (
        typeof action.target.type !== "string" ||
        action.target.type.trim() === ""
      ) {
        throw new Error(
          `authorized_actions[${index}].target.type is required`
        );
      }


      if (
        typeof action.target.value !== "string" ||
        action.target.value.trim() === ""
      ) {
        throw new Error(
          `authorized_actions[${index}].target.value is required`
        );
      }


      if (
        action.approval_request_id !==
        approval.approval_request_id
      ) {
        throw new Error(
          `authorized_actions[${index}] approval_request_id mismatch`
        );
      }


      if (
        typeof action.approved_by !== "string" ||
        action.approved_by.trim() === ""
      ) {
        throw new Error(
          `authorized_actions[${index}].approved_by is required`
        );
      }


      if (
        typeof action.approved_at !== "string" ||
        Number.isNaN(
          Date.parse(action.approved_at)
        )
      ) {
        throw new Error(
          `authorized_actions[${index}].approved_at must be a valid ISO timestamp`
        );
      }


      return {

        execution_id:
          `${approval.alert_id}-${action.action_id}`,

        action_id:
          action.action_id,

        action:
          action.action,

        target:
          {
            type:
              action.target.type,

            value:
              action.target.value
          },

        priority:
          action.priority || "medium",

        reason:
          action.reason || "",

        evidence_sources:
          Array.isArray(action.evidence_sources)
            ? action.evidence_sources
            : [],

        authorization:
          {
            approval_request_id:
              approval.approval_request_id,

            approved_by:
              action.approved_by,

            approved_at:
              action.approved_at
          }
      };
    }
  );


// --------------------------------------------------
// 3. Build execution authorization envelope
// --------------------------------------------------

return [
  {
    json: {

      response_execution_authorization_version:
        "1.0",

      alert_id:
        approval.alert_id,

      status:
        "authorized_for_execution",

      execution_authorized:
        true,

      approval_request_id:
        approval.approval_request_id,

      authorized_action_count:
        canonicalActions.length,

      authorized_actions:
        canonicalActions
    }
  }
];

// ==================================================
// Response Execution Not Authorized
//
// Terminal control path when the approval state does
// not authorize execution.
// ==================================================

const input = $json;


return [
  {
    json: {

      response_execution_authorization_version:
        "1.0",

      alert_id:
        input?.alert_id ?? null,

      status:
        "not_authorized",

      execution_authorized:
        false,

      approval_valid:
        input?.valid === true,

      approved:
        input?.approved === true,

      rejected:
        input?.rejected === true,

      errors:
        Array.isArray(input?.errors)
          ? input.errors
          : [],

      authorized_actions:
        []
    }
  }
];
